q = [p for p in json.load(open('agent/queue.json', encoding='utf-8')) if '-wed' not in p['id']]
for date, n, title, tag, text in P:
    img = f'img/{date}-wed{n}.png'
    old = date < '2026-11-11'
    if not os.path.exists(img):
        if old: O.card(title, tag, img)
        else: N.make(title.replace('|', ' '), tag, img)
    q.append({'id': f'linkedin-{date}-wed{n}', 'platform': 'linkedin', 'date': date, 'time': '09:00',
              'identity': 'old' if old else 'new', 'source': f'15-linkedin-posts#{n}', 'media': img, 'text': text})
q.sort(key=lambda p: (p['date'], p.get('time', '')))
json.dump(q, open('agent/queue.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print('أُضيف', len(P), 'بوستات أربعاء')
